// 產出 12 個任務：6 年級 × 2 科目
const grades = ['小一', '小二', '小三', '小四', '小五', '小六'];
const subjects = ['英文', '數學'];

// 114學年度 旭光國小教科書版本
const gradeEnglish = {
  '小一': '康軒Wonder World',
  '小二': '康軒Wonder World',
  '小三': '康軒Wonder World',
  '小四': '康軒Wonder World',
  '小五': '何嘉仁Super Fun',
  '小六': '康軒Wonder World',
};
const gradeMath = {
  '小一': '康軒',
  '小二': '翰林',
  '小三': '康軒',
  '小四': '南一',
  '小五': '康軒',
  '小六': '南一',
};

const now = new Date();
const month = now.getMonth();
const semester = (month >= 7 || month <= 0) ? '上學期' : '下學期';
const acadYear = now.getFullYear() - 1911 + (month >= 7 ? 0 : -1);
const acadYearLabel = `${acadYear}學年度`;

const tasks = [];
for (const grade of grades) {
  for (const subject of subjects) {
    const curriculum = subject === '英文' ? gradeEnglish[grade] : gradeMath[grade];
    tasks.push({ grade, subject, curriculum, semester, acadYear: acadYearLabel, qType: '標準題型', count: 3 });
  }
}
return tasks.map(t => ({ json: t }));

const openrouterResp = $input.item.json;
const taskItem = $('建立出題任務清單').item.json;

const grade = taskItem.grade || '';
const subject = taskItem.subject || '';
const curriculum = taskItem.curriculum || '';
const semester = taskItem.semester || '';
const acadYear = taskItem.acadYear || '';
const qType = taskItem.qType || '標準題型';

let raw = openrouterResp.choices?.[0]?.message?.content || '';
raw = raw.replace(/```json/g, '').replace(/```/g, '').trim();

let questions = [];
try {
  const first = raw.indexOf('[');
  const last = raw.lastIndexOf(']');
  if (first !== -1 && last > first) {
    questions = JSON.parse(raw.slice(first, last + 1));
  }
} catch (e) {
  console.error('Parse error:', e.message, raw.slice(0, 200));
  return [];
}

const subjectCode = subject === '英文' ? 'en' : 'ma';
const gradeCode = { '小一': 1, '小二': 2, '小三': 3, '小四': 4, '小五': 5, '小六': 6 }[grade] || 0;
const ts = Date.now();

const now = new Date();
const dayOfWeek = now.getDay();
const daysToSat = (6 - dayOfWeek + 7) % 7 || 7;
const nextSat = new Date(now);
nextSat.setDate(now.getDate() + daysToSat);
nextSat.setHours(1, 0, 0, 0);

return questions.map((q, i) => ({ json: {
  questionId: subjectCode + '-' + gradeCode + '-' + ts + '-' + (i + 1),
  grade, subject, curriculum, semester, acadYear, qType,
  chapter: q.chapter || '',
  question: q.question || '',
  optionA: q.optionA || '',
  optionB: q.optionB || '',
  optionC: q.optionC || '',
  optionD: q.optionD || '',
  answer: q.answer || 'A',
  concept: q.concept || '',
  mistake: q.mistake || '',
  hint: q.hint || '',
  publishDate: nextSat.toISOString()
}}));

const items = $input.all();
const count = items.length;
const now = new Date().toLocaleString('zh-TW', { timeZone: 'Asia/Taipei' });
return [{ json: {
  count,
  lineMsg: `【Mina 自動出題完成】
本月共新增 ${count} 道題目至 Notion 題庫
狀態：待審核
請登入 Notion 審核後勾選「是否發布」
時間：${now}`,
  emailSubject: `【Mina 題庫】${count} 道新題目待審核`,
  emailBody: `Mina AI 自動出題完成

共新增：${count} 道題
狀態：待審核

請登入 Notion 題庫 Database，
確認題目無誤後勾選「是否發布」=✓

時間：${now}`
}}];
